description.example_query:
Milvus(伪代码): search(collection='reviews', vector=embed(query_text), topK=1000)
SQL(取回评论元信息): SELECT review_id, business_id, stars, date, text FROM review WHERE review_id IN (...);
SQL(交集/补充商家信息): SELECT * FROM business WHERE business_id IN (...);

/* Milvus: search taste_vector in reviews collection */
# search(taste_vector, topK=200)

/* SQLite: map hits back to target business */
SELECT r.review_id, r.user_id, r.stars, r.text
FROM review r
WHERE r.business_id = '<TARGET_BUSINESS_ID>'
  AND r.review_id IN ('<HIT_REVIEW_ID_1>', '<HIT_REVIEW_ID_2>', ...);

/* 朋友数通常需要在应用层由friends字符串拆分计数 */
SELECT user_id, name, review_count, friends
FROM user
WHERE user_id IN ( ... );

/* Milvus伪代码 */
collection.search(
  data=[query_vec],
  anns_field='embedding',
  limit=50,
  expr='business_id in ["id1","id2",...]'
)

/* SQLite取回评论原文 */
SELECT review_id, business_id, user_id, stars, date, text
FROM review
WHERE review_id IN (....);

SELECT user_id, name, average_stars, review_count, yelping_since
FROM user
WHERE user_id IN (....);
